import{_ as e,o as d,c as o,ao as i}from"./chunks/framework.CkURMYgQ.js";const y=JSON.parse('{"title":"Model parameters","description":"","frontmatter":{},"headers":[],"relativePath":"parameters.md","filePath":"parameters.md","lastUpdated":null}'),r={name:"parameters.md"};function n(a,t,s,l,c,g){return d(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="Model-parameters" tabindex="-1">Model parameters <a class="header-anchor" href="#Model-parameters" aria-label="Permalink to &quot;Model parameters {#Model-parameters}&quot;">​</a></h1><p>Every option is set through <a href="/GEMB.jl/previews/PR71/api#GEMB.initialize_parameters"><code>initialize_parameters</code></a>, which validates each value at construction. <strong>Defaults are in bold.</strong> Physics defaults follow the two firn-model intercomparisons — RetMIP (Vandecrux et al., 2020) and FirnMICE (Lundin et al., 2017) — and, where those are silent, the shipped configurations of the <a href="https://github.com/UWGlaciology/CommunityFirnModel" target="_blank" rel="noreferrer">Community Firn Model</a> and <a href="https://github.com/IMAU-ice-and-climate/IMAU-FDM" target="_blank" rel="noreferrer">IMAU-FDM</a>. Each option&#39;s full citation and rationale is in the <a href="/GEMB.jl/previews/PR71/api#GEMB.ModelParameters"><code>ModelParameters</code></a> docstring.</p><h2 id="Method-options" tabindex="-1">Method options <a class="header-anchor" href="#Method-options" aria-label="Permalink to &quot;Method options {#Method-options}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Options</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>densification_method</code></td><td style="text-align:right;"><strong><code>:Arthern</code></strong>, <code>:ArthernB</code>, <code>:HerronLangway</code>, <code>:Barnola1991</code>, <code>:Crocus</code>, <code>:CrocusPure</code>, <code>:GSFC2020</code>, <code>:Simonsen2013</code>, <code>:Ligtenberg</code></td><td style="text-align:right;">Firn compaction law. FirnMICE finds the raw <code>:Arthern</code> (k₀=k₁=1) the most accumulation-sensitive of the eight schemes tested; <code>:Ligtenberg</code> and <code>:GSFC2020</code> are its recalibrated successors and are worth considering for a specific domain</td></tr><tr><td style="text-align:right;"><code>densification_accumulation</code></td><td style="text-align:right;"><strong><code>:accumulation</code></strong>, <code>:precipitation</code></td><td style="text-align:right;">Whether compaction is driven by mean snowfall or by mean total precipitation</td></tr><tr><td style="text-align:right;"><code>thermal_conductivity_method</code></td><td style="text-align:right;"><strong><code>:Calonne2019</code></strong>, <code>:Calonne2019Air</code>, <code>:Calonne</code>, <code>:Sturm</code>, <code>:Marchenko2019</code></td><td style="text-align:right;">RetMIP §5.1 recommends <code>:Calonne2019</code> by name; the CFM and IMAU-FDM both ship it. <code>:Calonne2019Air</code> carries the air-conductivity ratio of eq. 5 on the snow branch as IMAU-FDM does</td></tr><tr><td style="text-align:right;"><code>thermal_solver</code></td><td style="text-align:right;"><strong><code>ExplicitThermal()</code></strong>, <code>ImplicitThermal()</code></td><td style="text-align:right;">Thermal integration scheme, selected by <em>type</em> rather than by <code>Symbol</code>. <code>ExplicitThermal</code> sub-steps to the Von Neumann stability limit, so its cost is set by the stiffest cell; <code>ImplicitThermal</code> is backward Euler on a tridiagonal system, unconditionally stable, and sub-steps only for accuracy. The explicit default is faster on a well-conditioned column (measured 2.4 s vs 5.8 s over a year of 3-hourly forcing) and is what the implicit path is validated against; the implicit path is the robust choice when thin refrozen lenses collapse the stability limit</td></tr><tr><td style="text-align:right;"><code>thermal_explicit_safety_factor</code></td><td style="text-align:right;"><strong><code>0.8</code></strong>, any value in (0, 1]</td><td style="text-align:right;">Fraction of the diffusive stability limit <code>ExplicitThermal</code> may sub-step at; unread by <code>ImplicitThermal</code>. Not slack against an imprecise limit: <code>_max_safe_dt</code> bounds diffusion only, while the surface cell also carries the surface energy balance&#39;s feedback <code>Λ = dQ/dT₁ ≤ 0</code> in the same coefficient, and nothing in the model bounds <code>Λ</code>. Over a year of 3-hourly forcing at the synthetic site the realized surface amplification factor stayed ≤ 0.955 at 0.8 but exceeded 1 on 0.65% of steps at 0.95, for ~17% fewer sub-steps. Raise it toward 1.0 to trade monotonicity margin for speed on a well-conditioned column; use <code>ImplicitThermal()</code> if the step limit should be gone rather than loosened</td></tr><tr><td style="text-align:right;"><code>heat_capacity_method</code></td><td style="text-align:right;"><strong><code>:constant</code></strong>, <code>:CuffeyPaterson</code></td><td style="text-align:right;"><code>:constant</code> (2102 J kg⁻¹ K⁻¹) matches the CFM&#39;s melt-enabled path; <code>:CuffeyPaterson</code> is <code>152.5 + 7.122·T</code></td></tr><tr><td style="text-align:right;"><code>rain_heat_capacity</code></td><td style="text-align:right;"><strong><code>:water</code></strong>, <code>:ice</code></td><td style="text-align:right;">Heat capacity carrying rain&#39;s sensible heat above the melting point</td></tr><tr><td style="text-align:right;"><code>mean_temperature_method</code></td><td style="text-align:right;"><strong><code>:arithmetic</code></strong>, <code>:arrhenius</code></td><td style="text-align:right;">How the mean annual temperature driving densification is averaged</td></tr><tr><td style="text-align:right;"><code>grain_growth_method</code></td><td style="text-align:right;"><strong><code>:Arthern</code></strong>, <code>:Marbouty</code>, <code>:hybrid</code></td><td style="text-align:right;">Dry non-dendritic grain growth. The CFM ships <code>:Arthern</code>; <code>:Marbouty</code> stops dead at 400 kg m⁻³</td></tr><tr><td style="text-align:right;"><code>water_irreducible_method</code></td><td style="text-align:right;"><strong><code>:ColeouLesaffre</code></strong>, <code>:constant</code></td><td style="text-align:right;">Both the CFM and IMAU-FDM use Coléou &amp; Lesaffre; RetMIP §5.4 ties the flat 0.07 to under-retention in the percolation zone</td></tr><tr><td style="text-align:right;"><code>melt_geometry</code></td><td style="text-align:right;"><strong><code>:thickness</code></strong>, <code>:density</code></td><td style="text-align:right;">What melting does to a cell: shrink <code>dz</code> at fixed density (Crocus) or lower density at fixed <code>dz</code> (SNOWPACK). Only <code>:density</code> makes a melt–refreeze cycle return the geometry as well as the mass</td></tr><tr><td style="text-align:right;"><code>runoff_method</code></td><td style="text-align:right;"><strong><code>:instantaneous</code></strong>, <code>:ZuoOerlemans</code>, <code>:Darcy</code></td><td style="text-align:right;">All three RetMIP bucket lineages and both comparison models run instantaneous. The other two give a drainage timescale and permit firn aquifers</td></tr><tr><td style="text-align:right;"><code>new_snow_method</code></td><td style="text-align:right;"><strong><code>:Constant350</code></strong>, <code>:Constant315</code>, <code>:Constant150</code>, <code>:Fausto</code>, <code>:FaustoFit</code>, <code>:Pahaut</code>, <code>:Kaspers</code>, <code>:KuipersMunneke</code></td><td style="text-align:right;">Fresh-snow density. The CFM ships a constant 350. <code>:Constant*</code> are bare constants; <code>:Fausto</code>/<code>:FaustoFit</code>/<code>:Pahaut</code> also select the Crocus wind-dependent fresh-grain properties. <code>:Pahaut</code> is the only alpine-seasonal-snow fit — prefer it for temperate and mid-latitude glaciers, where the polar fits run too dense</td></tr><tr><td style="text-align:right;"><code>blowing_snow_method</code></td><td style="text-align:right;"><strong><code>:none</code></strong>, <code>:Crocus</code></td><td style="text-align:right;">Wind rework of snow already on the ground. <code>:Crocus</code> is the SURFEX/Crocus <code>SNOWDRIFT</code> scheme (Vionnet et al., 2012; Lafaysse et al., 2026 eqs. 59–66) — the only one of the three reference implementations that computes blowing snow at all (the CFM has none; IMAU-FDM imports it from RACMO). Exactly mass-conserving on its own: it compacts and fragments, it does not erode. Set <code>blowing_snow_sublimation</code> for the one term that removes mass, or <code>drift_rate</code> for the prescribed path</td></tr><tr><td style="text-align:right;"><code>albedo_method</code></td><td style="text-align:right;"><strong><code>:GardnerSharp</code></strong>, <code>:BrunLefebre</code>, <code>:GreuellKonzelmann</code>, <code>:None</code></td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>emissivity_method</code></td><td style="text-align:right;"><strong><code>:uniform</code></strong>, <code>:grain_radius_threshold</code>, <code>:grain_radius_w_threshold</code></td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>initialize_age</code></td><td style="text-align:right;"><strong><code>:steady_state</code></strong>, <code>:zero</code></td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>output_frequency</code></td><td style="text-align:right;"><strong><code>:all</code></strong>, <code>:daily</code>, <code>:weekly</code>, <code>:monthly</code>, <code>:last</code></td><td style="text-align:right;"></td></tr></tbody></table><h2 id="Physical-and-numerical-settings" tabindex="-1">Physical and numerical settings <a class="header-anchor" href="#Physical-and-numerical-settings" aria-label="Permalink to &quot;Physical and numerical settings {#Physical-and-numerical-settings}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Parameter</th><th style="text-align:right;">Default</th><th style="text-align:right;">Units</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>density_ice</code></td><td style="text-align:right;"><strong>917.0</strong></td><td style="text-align:right;">kg m⁻³</td><td style="text-align:right;">Pure-ice density. Matches the CFM and IMAU-FDM, and the pure-ice density the Calonne (2019) conductivity and Barnola (1991) densification fits were built against</td></tr><tr><td style="text-align:right;"><code>water_irreducible_saturation</code></td><td style="text-align:right;"><strong>0.07</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Read only under <code>water_irreducible_method = :constant</code></td></tr><tr><td style="text-align:right;"><code>impermeable_density</code></td><td style="text-align:right;"><strong>830.0</strong></td><td style="text-align:right;">kg m⁻³</td><td style="text-align:right;">Flow-blocking criterion (CFM <code>RhoImp</code>). RetMIP models span 810–917</td></tr><tr><td style="text-align:right;"><code>impermeable_thickness</code></td><td style="text-align:right;"><strong>0.1</strong></td><td style="text-align:right;">m</td><td style="text-align:right;">Minimum blocking-lens thickness (CFM <code>ThickImp</code>)</td></tr><tr><td style="text-align:right;"><code>pore_saturation_max</code></td><td style="text-align:right;"><strong>1.0</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Cap on pore filling; only reachable when runoff is delayed</td></tr><tr><td style="text-align:right;"><code>heat_capacity_ice</code></td><td style="text-align:right;"><strong>2102.0</strong></td><td style="text-align:right;">J kg⁻¹ K⁻¹</td><td style="text-align:right;">Read only under <code>heat_capacity_method = :constant</code></td></tr><tr><td style="text-align:right;"><code>rain_temperature_threshold</code></td><td style="text-align:right;"><strong>273.15</strong></td><td style="text-align:right;">K</td><td style="text-align:right;">Rain/snow partition temperature</td></tr><tr><td style="text-align:right;"><code>emissivity</code></td><td style="text-align:right;"><strong>0.97</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>emissivity_grain_radius_large</code></td><td style="text-align:right;"><strong>0.97</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>emissivity_grain_radius_threshold</code></td><td style="text-align:right;"><strong>10.0</strong></td><td style="text-align:right;">mm</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>surface_roughness_effective_ratio</code></td><td style="text-align:right;"><strong>0.10</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>albedo_snow</code> / <code>albedo_ice</code> / <code>albedo_fixed</code></td><td style="text-align:right;"><strong>0.85</strong> / <strong>0.48</strong> / <strong>0.85</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>albedo_density_threshold</code></td><td style="text-align:right;"><strong><code>Inf</code></strong></td><td style="text-align:right;">kg m⁻³</td><td style="text-align:right;"><code>Inf</code> disables the density-based snow/ice albedo switch</td></tr><tr><td style="text-align:right;"><code>cloud_fraction</code></td><td style="text-align:right;"><strong>0.1</strong></td><td style="text-align:right;">–</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>shortwave_subsurface_absorption</code></td><td style="text-align:right;"><strong><code>false</code></strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Absorb shortwave with depth rather than at the surface only</td></tr><tr><td style="text-align:right;"><code>shortwave_downward_diffuse</code>, <code>solar_zenith_angle</code>, <code>cloud_optical_thickness</code>, <code>black_carbon_snow</code>, <code>black_carbon_ice</code></td><td style="text-align:right;"><strong>0.0</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Overridden by the forcing when supplied</td></tr><tr><td style="text-align:right;"><code>column_ztop</code></td><td style="text-align:right;"><strong>10.0</strong></td><td style="text-align:right;">m</td><td style="text-align:right;">Depth of the uniform near-surface zone</td></tr><tr><td style="text-align:right;"><code>column_dztop</code></td><td style="text-align:right;"><strong>0.05</strong></td><td style="text-align:right;">m</td><td style="text-align:right;">Cell thickness in that zone</td></tr><tr><td style="text-align:right;"><code>column_dzmin</code> / <code>column_dzmax</code></td><td style="text-align:right;"><strong>0.025</strong> / <strong>0.075</strong></td><td style="text-align:right;">m</td><td style="text-align:right;">Merge/split bands enforcing the fixed cell count</td></tr><tr><td style="text-align:right;"><code>column_depth_max</code></td><td style="text-align:right;"><strong>250.0</strong></td><td style="text-align:right;">m</td><td style="text-align:right;"><em>Ceiling</em> on the constructed column depth, not the depth itself</td></tr><tr><td style="text-align:right;"><code>column_zy</code></td><td style="text-align:right;"><strong>1.10</strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Geometric growth ratio below <code>column_ztop</code></td></tr><tr><td style="text-align:right;"><code>horizontal_strain_rate</code></td><td style="text-align:right;"><strong>0.0</strong></td><td style="text-align:right;">yr⁻¹</td><td style="text-align:right;">Ice-dynamic layer thinning; 0 disables the term</td></tr><tr><td style="text-align:right;"><code>blowing_snow_sublimation</code></td><td style="text-align:right;"><strong><code>false</code></strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Whether <code>blowing_snow_method = :Crocus</code> also sublimates the suspended fraction (Gordon et al., 2006). Off is Crocus&#39;s own default (<code>OSNOWDRIFT_SUBLIM</code>), and it is the only part of the computed scheme that removes mass</td></tr><tr><td style="text-align:right;"><code>drift_rate</code></td><td style="text-align:right;"><strong>0.0</strong></td><td style="text-align:right;">kg m⁻² yr⁻¹</td><td style="text-align:right;">Prescribed net drift divergence, positive for erosion; 0 disables the term. A constant-rate shorthand for the <code>snow_drift</code> forcing layer, which takes precedence when the forcing carries one. Bounded to ±2000</td></tr><tr><td style="text-align:right;"><code>surface_slope</code></td><td style="text-align:right;"><strong>0.0</strong></td><td style="text-align:right;">m m⁻¹</td><td style="text-align:right;">Hydraulic gradient; read only under <code>:ZuoOerlemans</code>/<code>:Darcy</code></td></tr><tr><td style="text-align:right;"><code>output_viscosity</code></td><td style="text-align:right;"><strong><code>false</code></strong></td><td style="text-align:right;">–</td><td style="text-align:right;">Adds a <code>viscosity</code> output layer; populated only under <code>:Crocus</code>/<code>:CrocusPure</code></td></tr></tbody></table>',6)])])}const m=e(r,[["render",n]]);export{y as __pageData,m as default};
